  "version": "0.1.0",
  "private": true,
  "type": "module",
  "scripts": {
    "clean": "rm -rf dist results .cache src/generated",
    "generate": "node tools/generate-code.mjs",
    "build:bundle": "rolldown -c",
    "build:binaries": "node tools/build-binaries.mjs",
    "rebuild": "npm run clean && npm run generate && npm run build:bundle && npm run build:binaries",
    "bench": "node tools/run-bench.mjs"
  },
